"use strict";

// MAIN 시작화면 연속 곡면 데이터
const introSymbolField = {"width":768,"height":788,"data":""};

// MAIN 시작화면 입체 심볼
// 윤곽까지의 연속 거리로 곡면을 그려 삼각형 경계 없이 금속 심볼을 회전시킵니다.
function createIntroMetalSymbol(intro, timeline) {
  const canvas = document.createElement("canvas");
  const gl = canvas.getContext("webgl", { alpha: true, antialias: true, premultipliedAlpha: false });
  if (!gl || !gl.getShaderPrecisionFormat(gl.FRAGMENT_SHADER, gl.HIGH_FLOAT)?.precision) return () => {};
  const resources = [];
  let frameId = null;
  let disposed = false;

  // 셰이더를 컴파일하고 사용할 수 없으면 기본 심볼로 돌아갑니다.
  function compileShader(type, source) {
    const shader = gl.createShader(type);
    resources.push(["shader", shader]);
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error("Intro shader compile failed");
    return shader;
  }

  // 시작화면이 끝나면 렌더링과 그래픽 메모리를 정리합니다.
  function disposeMetalSymbol() {
    if (disposed) return;
    disposed = true;
    window.cancelAnimationFrame(frameId);
    canvas.removeEventListener("webglcontextlost", handleContextLost);
    for (const [type, resource] of resources) {
      if (type === "shader") gl.deleteShader(resource);
      if (type === "program") gl.deleteProgram(resource);
      if (type === "buffer") gl.deleteBuffer(resource);
      if (type === "texture") gl.deleteTexture(resource);
    }
    canvas.remove();
    intro.classList.remove("is-metal-ready");
  }

  // 그래픽 장치가 중단되면 기존 이미지로 복원합니다.
  function handleContextLost(event) {
    event.preventDefault();
    disposeMetalSymbol();
  }

  // 정밀 곡면 데이터를 비동기로 준비해 시작화면 표시를 막지 않습니다.
  async function prepareMetalSymbol() {
    try {
      const vertexShader = compileShader(gl.VERTEX_SHADER, `
        attribute vec2 aPosition;
        varying mediump vec2 vPosition;
        void main() {
          vPosition = aPosition;
          gl_Position = vec4(aPosition, 0.0, 1.0);
        }
      `);
      const fragmentShader = compileShader(gl.FRAGMENT_SHADER, `
        precision highp float;
        varying mediump vec2 vPosition;
        uniform sampler2D uField;
        uniform mat3 uRotation;
        uniform mat3 uInverseRotation;
        uniform vec3 uMetalColor;
        uniform float uAspect;
        uniform float uShapeAspect;

        float shapeDistance(vec3 p) {
          vec2 uv = vec2(p.x / uShapeAspect * 0.5 + 0.5, 0.5 - p.y * 0.5);
          vec2 encoded = texture2D(uField, uv).rg;
          float outline = ((encoded.r * 65280.0 + encoded.g * 255.0) / 65535.0 * 2.0 - 1.0) * 0.125;
          vec2 edge = vec2(outline + 0.016, abs(p.z) - 0.075 + 0.016);
          return min(max(edge.x, edge.y), 0.0) + length(max(edge, 0.0)) - 0.016;
        }

        vec3 surfaceNormal(vec3 p) {
          // 뾰족한 끝에서도 반사광이 갈라지지 않도록 주변 곡면을 함께 계산합니다.
          vec2 e = vec2(0.015, 0.0);
          return normalize(vec3(
            shapeDistance(p + e.xyy) - shapeDistance(p - e.xyy),
            shapeDistance(p + e.yxy) - shapeDistance(p - e.yxy),
            shapeDistance(p + e.yyx) - shapeDistance(p - e.yyx)
          ));
        }

        void main() {
          vec3 origin = uInverseRotation * vec3(0.0, 0.0, 4.5);
          vec3 ray = uInverseRotation * normalize(vec3(vPosition.x * uAspect, vPosition.y, -4.0));
          vec3 safeRay = sign(ray + vec3(0.0000000001)) * max(abs(ray), vec3(0.00001));
          vec3 box = vec3(uShapeAspect, 1.0, 0.105);
          vec3 entry = (-box - origin) / safeRay;
          vec3 exit = (box - origin) / safeRay;
          vec3 low = min(entry, exit);
          vec3 high = max(entry, exit);
          float start = max(max(low.x, low.y), low.z);
          float end = min(min(high.x, high.y), high.z);
          if (start > end || end < 0.0) discard;
          float travel = max(start, 0.0);
          bool hit = false;
          vec3 p;
          for (int index = 0; index < 96; index++) {
            p = origin + ray * travel;
            float distance = shapeDistance(p);
            if (distance < 0.0006) { hit = true; break; }
            travel += max(distance * 0.8, 0.0002);
            if (travel > end) break;
          }
          if (!hit) discard;
          vec3 normal = normalize(uRotation * surfaceNormal(p));
          vec3 worldPoint = uRotation * p;
          vec3 view = normalize(vec3(0.0, 0.0, 4.5) - worldPoint);
          vec3 reflected = reflect(-view, normal);
          float bandA = (reflected.x + reflected.y * 0.32 - 0.4) / 0.23;
          float bandB = (reflected.x - reflected.y * 0.5 + 0.6) / 0.15;
          float shine = exp(-bandA * bandA) * 0.75 + exp(-bandB * bandB) * 0.55;
          shine += smoothstep(-0.15, 0.75, reflected.y) * 0.6;
          float rim = pow(clamp(1.0 - abs(dot(normal, view)), 0.0, 1.0), 3.0);
          vec3 color = uMetalColor * (0.22 + shine * 0.55 + rim * 0.18);
          color += vec3(0.86, 0.85, 0.92) * (shine * 0.45 + rim * 0.16);
          gl_FragColor = vec4(color, 1.0);
        }
      `);
      const program = gl.createProgram();
      resources.push(["program", program]);
      gl.attachShader(program, vertexShader);
      gl.attachShader(program, fragmentShader);
      gl.linkProgram(program);
      if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error("Intro shader link failed");
      gl.useProgram(program);

      const buffer = gl.createBuffer();
      resources.push(["buffer", buffer]);
      gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
      const position = gl.getAttribLocation(program, "aPosition");
      gl.enableVertexAttribArray(position);
      gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

      // 16비트 곡면 데이터를 풀어 매끄럽게 보간되는 텍스처로 준비합니다.
      const encoded = Uint8Array.from(atob(introSymbolField.data), (character) => character.charCodeAt(0));
      const stream = new Blob([encoded]).stream().pipeThrough(new DecompressionStream("deflate"));
      const packed = new Uint8Array(await new Response(stream).arrayBuffer());
      if (disposed) return;
      const field = new Uint8Array(introSymbolField.width * introSymbolField.height * 4);
      for (let index = 0; index < packed.length / 2; index += 1) {
        field[index * 4] = packed[index * 2];
        field[index * 4 + 1] = packed[index * 2 + 1];
        field[index * 4 + 3] = 255;
      }
      const texture = gl.createTexture();
      resources.push(["texture", texture]);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, introSymbolField.width, introSymbolField.height, 0, gl.RGBA, gl.UNSIGNED_BYTE, field);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.uniform1i(gl.getUniformLocation(program, "uField"), 0);
      gl.uniform1f(gl.getUniformLocation(program, "uShapeAspect"), introSymbolField.width / introSymbolField.height);
      const rotationUniform = gl.getUniformLocation(program, "uRotation");
      const inverseUniform = gl.getUniformLocation(program, "uInverseRotation");
      const aspectUniform = gl.getUniformLocation(program, "uAspect");
      const color = getComputedStyle(document.documentElement).getPropertyValue("--color-purple-light").trim();
      const channels = /^#[\da-f]{6}$/i.test(color) ? color.slice(1).match(/../g).map((part) => parseInt(part, 16) / 255) : [0.89, 0.8, 1];
      gl.uniform3fv(gl.getUniformLocation(program, "uMetalColor"), channels);
      gl.clearColor(0, 0, 0, 0);
      canvas.className = "main-intro-canvas";
      canvas.setAttribute("aria-hidden", "true");
      intro.append(canvas);
      canvas.addEventListener("webglcontextlost", handleContextLost);
      const started = performance.now();

      // 연속 곡면을 고해상도로 렌더링하고 한 바퀴 회전 뒤 정면에서 멈춥니다.
      function drawMetalSymbol(now) {
        if (disposed || intro.hidden) return;
        const elapsed = Number(timeline?.currentTime ?? (now - started));
        const progress = Math.max(0, Math.min(1, (elapsed - 650) / 2750));
        const eased = progress * progress * (3 - 2 * progress);
        const yaw = eased * Math.PI * 2;
        const pitch = Math.sin(eased * Math.PI * 2) * 0.16;
        const cy = Math.cos(yaw), sy = Math.sin(yaw), cx = Math.cos(pitch), sx = Math.sin(pitch);
        const rotation = new Float32Array([cy, sx * sy, -cx * sy, 0, cx, sx, sy, -sx * cy, cx * cy]);
        const inverse = new Float32Array([rotation[0], rotation[3], rotation[6], rotation[1], rotation[4], rotation[7], rotation[2], rotation[5], rotation[8]]);
        const ratio = Math.min(Math.max(window.devicePixelRatio || 1, 2), 3);
        const scale = Math.min(ratio, 900 / Math.max(canvas.clientWidth, canvas.clientHeight, 1));
        const width = Math.max(1, Math.round(canvas.clientWidth * scale));
        const height = Math.max(1, Math.round(canvas.clientHeight * scale));
        if (canvas.width !== width || canvas.height !== height) { canvas.width = width; canvas.height = height; }
        gl.viewport(0, 0, width, height);
        gl.clear(gl.COLOR_BUFFER_BIT);
        gl.uniform1f(aspectUniform, width / height);
        gl.uniformMatrix3fv(rotationUniform, false, rotation);
        gl.uniformMatrix3fv(inverseUniform, false, inverse);
        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
        intro.classList.add("is-metal-ready");
        frameId = window.requestAnimationFrame(drawMetalSymbol);
      }

      drawMetalSymbol(started);
    } catch {
      disposeMetalSymbol();
    }
  }
  prepareMetalSymbol();
  return disposeMetalSymbol;
}


// MAIN 시작화면
// 첫 방문에만 시작화면을 보여주고 종료 후 메인배너 문구를 등장시킵니다.
function initMainIntro() {
  const intro = document.querySelector(".main-intro");
  if (!intro) {
    initHeaderSloganReveal();
    return;
  }
  let alreadySeen = false;
  try {
    alreadySeen = window.localStorage.getItem("plumky-main-intro-seen") === "1";
    if (!alreadySeen) window.localStorage.setItem("plumky-main-intro-seen", "1");
  } catch {
    // 브라우저가 저장소를 차단해도 메인 화면은 정상적으로 표시합니다.
  }
  if (alreadySeen) {
    intro.hidden = true;
    initHeaderSloganReveal();
    return;
  }
  intro.hidden = false;
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
  const duration = reducedMotion.matches ? 100 : 5000;
  const animation = intro.getAnimations?.().find((item) => item.animationName === "main-intro-exit");
  const remaining = Math.max(0, duration - Number(animation?.currentTime || 0));
  const content = [...document.querySelectorAll(".site-header, main, .site-footer")];
  const inertBefore = content.map((element) => element.inert);
  let finished = false;
  let fallbackId;
  let disposeSymbol = () => {};

  // CSS 애니메이션 종료나 예외 종료 시 시작화면을 한 번만 정리합니다.
  function finishMainIntro() {
    if (finished) return;
    finished = true;
    window.clearTimeout(fallbackId);
    disposeSymbol();
    intro.hidden = true;
    document.documentElement.classList.remove("is-intro-active");
    content.forEach((element, index) => { element.inert = inertBefore[index]; });
    intro.removeEventListener("animationend", handleIntroEnd);
    reducedMotion.removeEventListener("change", finishMainIntro);
    initHeaderSloganReveal();
  }

  // 심볼 회전이 아닌 전체 시작화면의 종료 이벤트만 처리합니다.
  function handleIntroEnd(event) {
    if (event.target === intro && event.animationName === "main-intro-exit") finishMainIntro();
  }

  if (remaining === 0) {
    finishMainIntro();
    return;
  }
  document.documentElement.classList.add("is-intro-active");
  content.forEach((element) => { element.inert = true; });
  intro.addEventListener("animationend", handleIntroEnd);
  reducedMotion.addEventListener("change", finishMainIntro);
  fallbackId = window.setTimeout(finishMainIntro, remaining + 100);
  if (!reducedMotion.matches) disposeSymbol = createIntroMetalSymbol(intro, animation);
}

initMainIntro();

// MAIN 메인배너 문구 스크롤 애니메이션
// 화면에 들어오는 헤더 문구를 아래에서 위로 한 번씩 나타나게 준비합니다.
function initHeaderSloganReveal() {
  const slogans = document.querySelectorAll(".header-slogan");
  if (!slogans.length || !("IntersectionObserver" in window)
    || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

  // 문구가 화면에 들어오면 애니메이션을 실행하고 관찰을 종료합니다.
  function revealSlogans(entries, observer) {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add("is-visible");
      observer.unobserve(entry.target);
    });
  }

  const observer = new IntersectionObserver(revealSlogans, {
    threshold: 0.15,
    rootMargin: "0px 0px -24px 0px",
  });

  // 각 문구의 시작 위치를 설정한 뒤 화면 진입 여부를 관찰합니다.
  slogans.forEach((slogan) => {
    slogan.classList.add("is-reveal-ready");
    observer.observe(slogan);
  });
}

// PRODUCT LIPS 슬라이더
// 오른쪽 제품 영역에만 마우스 드래그와 터치 스와이프를 적용합니다.
function initLipsSlider() {
  const container = document.querySelector(".lips-swiper");
  if (!container || typeof window.Swiper !== "function") return;
  const section = container.closest(".lips-section");
  const mobile = window.matchMedia("(max-width: 600px)");
  const tablet = window.matchMedia("(max-width: 1024px)");
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

  // 화면 크기에 맞는 카드 수와 카드 사이 여백을 계산합니다.
  function getLipsLayout() {
    return {
      slidesPerView: mobile.matches ? 1 : 2,
      spaceBetween: mobile.matches ? 16 : tablet.matches ? 24 : window.innerWidth * 51 / 1920,
    };
  }

  // 페이지 선택 버튼에 키보드로 접근할 수 있는 이름을 지정합니다.
  function renderLipsBullet(index, className) {
    return `<button type="button" class="${className}" aria-label="${index + 1}번째 제품 보기"></button>`;
  }

  const slider = new window.Swiper(container, {
    ...getLipsLayout(),
    loop: true,
    speed: reducedMotion.matches ? 0 : 550,
    grabCursor: true,
    simulateTouch: true,
    threshold: 8,
    watchOverflow: true,
    keyboard: { enabled: true, onlyInViewport: true },
    navigation: {
      prevEl: section.querySelector(".lips-prev"),
      nextEl: section.querySelector(".lips-next"),
    },
    pagination: {
      el: section.querySelector(".lips-pagination"),
      clickable: true,
      renderBullet: renderLipsBullet,
    },
    a11y: {
      prevSlideMessage: "이전 제품",
      nextSlideMessage: "다음 제품",
      slideLabelMessage: "{{slidesLength}}개 중 {{index}}번째 제품",
      paginationBulletMessage: "{{index}}번째 제품 보기",
    },
  });

  // 화면을 바꾸면 카드 수와 여백을 다시 적용합니다.
  function updateLipsLayout() {
    Object.assign(slider.params, getLipsLayout());
    slider.params.speed = reducedMotion.matches ? 0 : 550;
    slider.update();
  }

  window.addEventListener("resize", updateLipsLayout);
  reducedMotion.addEventListener("change", updateLipsLayout);
}

initLipsSlider();

// PRODUCT LIPS·CASE 모델 호버 영상
// 모델·제품 영역의 마우스 호버와 슬라이드 조작 중 모델 이미지를 영상으로 전환합니다.
function initProductModelVideo(sectionName) {
  const layout = document.querySelector(`.${sectionName}-layout`);
  const model = layout?.querySelector(`.${sectionName}-model`);
  const video = model?.querySelector(`.${sectionName}-model-video`);
  const controls = layout?.querySelector(`.${sectionName}-slider-reveal`);
  if (!model || !video || !controls) return;
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
  let hovered = false;
  let interacting = false;
  let releaseTimer = null;
  let completed = false;

  // 호버·조작 상태에 따라 영상을 재생하거나 정지하고 기본 사진을 복원합니다.
  function updateModelVideo() {
    if ((hovered || interacting) && !completed && !reducedMotion.matches && !document.hidden) {
      const playback = video.play();
      playback?.catch(() => model.classList.remove("is-video-playing"));
    } else {
      model.classList.remove("is-video-playing");
      video.pause();
    }
  }

  // 실제 영상 프레임이 준비된 경우에만 사진 위로 부드럽게 표시합니다.
  function showPlayingVideo() {
    if ((hovered || interacting) && !completed && !reducedMotion.matches && !document.hidden) {
      model.classList.add("is-video-playing");
    } else {
      video.pause();
    }
  }

  // 마우스나 펜이 모델·제품 영역에 들어오면 영상을 재생합니다.
  function handleModelEnter(event) {
    if (event.pointerType !== "mouse" && event.pointerType !== "pen") return;
    if (completed) {
      completed = false;
      video.currentTime = 0;
    }
    hovered = true;
    updateModelVideo();
  }

  // 마우스가 영역을 벗어나면 조작 중인 경우를 제외하고 사진으로 돌아갑니다.
  function handleModelLeave() {
    hovered = false;
    updateModelVideo();
  }

  // 제품 드래그가 시작되면 터치 환경에서도 모델 영상을 재생합니다.
  function beginModelInteraction() {
    window.clearTimeout(releaseTimer);
    if (completed && !hovered) {
      completed = false;
      video.currentTime = 0;
    }
    interacting = true;
    updateModelVideo();
  }

  // 스와이프나 버튼 조작 후에도 영상의 원래 재생 시간이 끝날 때까지 유지합니다.
  function endModelInteraction() {
    if (!interacting) return;
    window.clearTimeout(releaseTimer);
    if (!Number.isFinite(video.duration) || video.duration <= 0) return;
    releaseTimer = window.setTimeout(() => {
      interacting = false;
      updateModelVideo();
    }, Math.max(0, video.duration - video.currentTime) * 1000 + 100);
  }

  // 영상이 한 번 끝나면 같은 호버 상태에서는 재생하지 않고 사진을 유지합니다.
  function finishModelVideo() {
    window.clearTimeout(releaseTimer);
    completed = true;
    interacting = false;
    model.classList.remove("is-video-playing");
    video.pause();
  }

  // 페이지 버튼 클릭이나 키보드 방향키로 슬라이드를 바꿔도 영상을 재생합니다.
  function handleModelControl(event) {
    if (event.type === "keydown" && !["ArrowLeft", "ArrowRight", "Enter", " "].includes(event.key)) return;
    beginModelInteraction();
    endModelInteraction();
  }

  // 화면을 벗어나거나 재생이 불가능하면 영상과 상호작용 상태를 정리합니다.
  function resetModelVideo() {
    window.clearTimeout(releaseTimer);
    hovered = false;
    interacting = false;
    model.classList.remove("is-video-playing");
    video.pause();
  }

  layout.addEventListener("pointerenter", handleModelEnter);
  layout.addEventListener("pointerleave", handleModelLeave);
  controls.addEventListener("pointerdown", beginModelInteraction, { passive: true });
  controls.addEventListener("click", handleModelControl);
  controls.addEventListener("keydown", handleModelControl);
  window.addEventListener("pointerup", endModelInteraction);
  window.addEventListener("pointercancel", resetModelVideo);
  window.addEventListener("blur", resetModelVideo);
  document.addEventListener("visibilitychange", resetModelVideo);
  reducedMotion.addEventListener("change", resetModelVideo);
  video.addEventListener("playing", showPlayingVideo);
  video.addEventListener("ended", finishModelVideo);
  video.addEventListener("loadedmetadata", endModelInteraction);
  video.addEventListener("error", resetModelVideo);
  if ("IntersectionObserver" in window) {
    // 해당 제품 섹션이 화면에서 완전히 사라지면 백그라운드 재생을 멈춥니다.
    const observer = new IntersectionObserver((entries) => {
      if (!entries[0].isIntersecting) resetModelVideo();
    });
    observer.observe(layout);
  }
}

initProductModelVideo("lips");
initProductModelVideo("case");

// PRODUCT LIPS 제목 스크롤 애니메이션
// PRODUCT와 LIPS 제목이 화면에 들어오면 아래에서 위로 나타나게 준비합니다.
function initLipsTitleReveal() {
  const titles = document.querySelectorAll(".lips-intro h2, .lips-heading");
  if (!titles.length || !("IntersectionObserver" in window)
    || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

  // 화면에 들어온 제목의 애니메이션을 한 번 실행합니다.
  function revealLipsTitles(entries, observer) {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add("is-visible");
      observer.unobserve(entry.target);
    });
  }

  const observer = new IntersectionObserver(revealLipsTitles, {
    threshold: 0.15,
    rootMargin: "0px 0px -24px 0px",
  });

  // 제목마다 애니메이션 시작 상태를 지정하고 화면 진입을 관찰합니다.
  titles.forEach((title) => {
    title.classList.add("lips-title-reveal");
    observer.observe(title);
  });
}

